// Extract payload from Bubble
const payload = $input.first().json.body || $input.first().json;

const authorId = payload.author_id || 'UNKNOWN_AUTHOR';
const authorName = payload.author_name || 'Author';
const authorEmail = payload.author_email || '';
const books = Array.isArray(payload.books) ? payload.books : [];

// Calculate consolidated financials
let totalEarned = 0;
let totalPaid = 0;
let totalPending = 0;
let publishedCount = 0;
let inProductionCount = 0;

const publishedBooks = [];
const inProductionBooks = [];

books.forEach(b => {
  const earned = Number(b.total_royalty_earned || 0);
  const paid = Number(b.royalty_paid || 0);
  const pending = Number(b.royalty_pending || 0);

  totalEarned += earned;
  totalPaid += paid;
  totalPending += pending;

  if (b.status && b.status.toLowerCase().includes('in production')) {
    inProductionCount++;
    inProductionBooks.push({
      title: b.title,
      isbn: b.isbn || 'Pending Allocation',
      status: b.status,
      genre: b.genre
    });
  } else {
    publishedCount++;
    publishedBooks.push({
      title: b.title,
      isbn: b.isbn,
      mrp: b.mrp,
      sold: b.total_copies_sold,
      earned: earned,
      paid: paid,
      pending: pending,
      lastPayout: b.last_royalty_payout_date || 'No Payout Recorded',
      platforms: b.available_on
    });
  }
});

// Determine payout cycle context according to BookLeaf Policy
// 80/20 Net Split, Quarterly schedule, 45-day post quarter window, Rs 1000 rollover threshold
const isRollover = totalPending > 0 && totalPending < 1000;
const isEligible = totalPending >= 1000;
const isFullySettled = totalPending === 0;

return [{
  json: {
    authorId,
    authorName,
    authorEmail,
    totalBooks: books.length,
    publishedCount,
    inProductionCount,
    financials: {
      totalEarned,
      totalPaid,
      totalPending,
      isRollover,
      isEligible,
      isFullySettled
    },
    publishedBooks,
    inProductionBooks,
    triggeredAt: new Date().toISOString(),
    triggeredBy: payload.triggered_by || 'Operations Admin'
  }
}];

